from __future__ import annotations

import re
from dataclasses import dataclass


_VERSION_RE = re.compile(
    r"^(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


def parse(text: str) -> Version:
    """Parse a version string."""
    if not isinstance(text, str):
        raise ValueError("version must be a string")

    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid semantic version: {text!r}")

    prerelease_text = match.group(4)
    prerelease: tuple[str, ...] = ()
    if prerelease_text is not None:
        prerelease = tuple(prerelease_text.split("."))
        for identifier in prerelease:
            if (
                identifier.isdigit()
                and len(identifier) > 1
                and identifier[0] == "0"
            ):
                raise ValueError(
                    f"invalid leading zero in pre-release identifier: {identifier!r}"
                )

    build_text = match.group(5)
    build = tuple(build_text.split(".")) if build_text is not None else ()

    return Version(
        int(match.group(1)),
        int(match.group(2)),
        int(match.group(3)),
        prerelease,
        build,
    )


def _coerce(value: str | Version) -> Version:
    return value if isinstance(value, Version) else parse(value)


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    left = _coerce(a)
    right = _coerce(b)

    for attribute in ("major", "minor", "patch"):
        lv = getattr(left, attribute)
        rv = getattr(right, attribute)
        if lv != rv:
            return -1 if lv < rv else 1

    if not left.prerelease and not right.prerelease:
        return 0
    if not left.prerelease:
        return 1
    if not right.prerelease:
        return -1

    for lv, rv in zip(left.prerelease, right.prerelease):
        lv_numeric = lv.isdigit()
        rv_numeric = rv.isdigit()
        if lv_numeric and rv_numeric:
            li, ri = int(lv), int(rv)
            if li != ri:
                return -1 if li < ri else 1
        elif lv_numeric != rv_numeric:
            return -1 if lv_numeric else 1
        elif lv != rv:
            return -1 if lv < rv else 1

    if len(left.prerelease) != len(right.prerelease):
        return -1 if len(left.prerelease) < len(right.prerelease) else 1
    return 0


def _parse_comparator(token: str) -> tuple[str, Version]:
    for operator in (">=", "<=", ">", "<", "=", "^", "~"):
        if token.startswith(operator):
            version_text = token[len(operator) :]
            if not version_text:
                raise ValueError(f"invalid comparator: {token!r}")
            return operator, parse(version_text)
    return "=", parse(token)


def _parse_range(range_: str) -> list[list[tuple[str, Version]]]:
    if not isinstance(range_, str):
        raise ValueError("range must be a string")

    sets: list[list[tuple[str, Version]]] = []
    for part in range_.split("||"):
        tokens = part.split()
        if not tokens:
            raise ValueError(f"invalid range: {range_!r}")
        sets.append([_parse_comparator(token) for token in tokens])
    return sets


def _satisfies_set(version: Version, comparators: list[tuple[str, Version]]) -> bool:
    for operator, target in comparators:
        comparison = compare(version, target)
        if operator == "=":
            ok = comparison == 0
        elif operator == ">":
            ok = comparison > 0
        elif operator == ">=":
            ok = comparison >= 0
        elif operator == "<":
            ok = comparison < 0
        elif operator == "<=":
            ok = comparison <= 0
        elif operator == "^":
            if target.major != 0:
                upper = Version(target.major + 1, 0, 0)
            elif target.minor != 0:
                upper = Version(0, target.minor + 1, 0)
            else:
                upper = Version(0, 0, target.patch + 1)
            ok = comparison >= 0 and compare(version, upper) < 0
        else:  # "~"
            upper = Version(target.major, target.minor + 1, 0)
            ok = comparison >= 0 and compare(version, upper) < 0
        if not ok:
            return False

    if version.prerelease:
        # A pre-release only matches when a comparator opts into that exact
        # MAJOR.MINOR.PATCH pre-release line.
        if not any(
            target.prerelease
            and target.major == version.major
            and target.minor == version.minor
            and target.patch == version.patch
            for _, target in comparators
        ):
            return False

    return True


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    parsed_version = _coerce(version)
    return any(
        _satisfies_set(parsed_version, comparators)
        for comparators in _parse_range(range_)
    )

from __future__ import annotations

import re
from datetime import date, datetime, timedelta


_MONTH_NAMES = {
    "JAN": 1,
    "FEB": 2,
    "MAR": 3,
    "APR": 4,
    "MAY": 5,
    "JUN": 6,
    "JUL": 7,
    "AUG": 8,
    "SEP": 9,
    "OCT": 10,
    "NOV": 11,
    "DEC": 12,
}

_DOW_NAMES = {
    "SUN": 0,
    "MON": 1,
    "TUE": 2,
    "WED": 3,
    "THU": 4,
    "FRI": 5,
    "SAT": 6,
}


def _resolve_value(
    token: str,
    names: dict[str, int] | None,
    minimum: int,
    maximum: int,
) -> int:
    token = token.strip()
    if names is not None and token.upper() in names:
        value = names[token.upper()]
    elif re.fullmatch(r"[0-9]+", token):
        value = int(token)
    else:
        raise ValueError(f"invalid cron value: {token!r}")

    if not minimum <= value <= maximum:
        raise ValueError(
            f"cron value {value} outside range {minimum}-{maximum}"
        )
    return value


def _parse_field(
    field: str,
    minimum: int,
    maximum: int,
    names: dict[str, int] | None = None,
) -> tuple[set[int], bool]:
    field = field.strip()
    if not field:
        raise ValueError("empty cron field")

    values: set[int] = set()
    for item in field.split(","):
        item = item.strip()
        if not item:
            raise ValueError("empty cron item")

        if item.count("/") > 1:
            raise ValueError(f"invalid cron item: {item!r}")

        has_step = "/" in item
        if has_step:
            base, step_text = item.split("/")
            if not re.fullmatch(r"[0-9]+", step_text):
                raise ValueError(f"invalid cron step: {step_text!r}")
            step = int(step_text)
            if step <= 0:
                raise ValueError("cron step must be positive")
        else:
            base = item
            step = 1

        if base == "*":
            start, end = minimum, maximum
            use_range = True
        elif "-" in base:
            if base.count("-") != 1:
                raise ValueError(f"invalid cron range: {base!r}")
            start_text, end_text = base.split("-")
            start = _resolve_value(start_text, names, minimum, maximum)
            end = _resolve_value(end_text, names, minimum, maximum)
            if start > end:
                raise ValueError(f"invalid cron range: {base!r}")
            use_range = True
        else:
            start = _resolve_value(base, names, minimum, maximum)
            if has_step:
                end = maximum
                use_range = True
            else:
                end = start
                use_range = False

        if use_range:
            values.update(range(start, end + 1, step))
        else:
            values.add(start)

    # A field is unrestricted only when it is literally "*".
    return values, field != "*"


def _day_matches(
    day: date,
    days_of_month: set[int],
    days_of_week: set[int],
    dom_restricted: bool,
    dow_restricted: bool,
) -> bool:
    dom_match = day.day in days_of_month
    cron_dow = (day.weekday() + 1) % 7
    dow_match = cron_dow in days_of_week

    if dom_restricted and dow_restricted:
        return dom_match or dow_match
    return dom_match and dow_match


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have five fields")

    minutes, _ = _parse_field(fields[0], 0, 59)
    hours, _ = _parse_field(fields[1], 0, 23)
    days_of_month, dom_restricted = _parse_field(fields[2], 1, 31)
    months, _ = _parse_field(fields[3], 1, 12, _MONTH_NAMES)
    days_of_week, dow_restricted = _parse_field(fields[4], 0, 7, _DOW_NAMES)

    # Cron treats both 0 and 7 as Sunday.
    days_of_week = {0 if value == 7 else value for value in days_of_week}

    start = after.replace(second=0, microsecond=0)
    if start <= after:
        start += timedelta(minutes=1)

    sorted_hours = sorted(hours)
    sorted_minutes = sorted(minutes)
    day = start.date()
    last_day = day + timedelta(days=366 * 5)

    while day <= last_day:
        if day.month in months and _day_matches(
            day,
            days_of_month,
            days_of_week,
            dom_restricted,
            dow_restricted,
        ):
            for hour in sorted_hours:
                for minute in sorted_minutes:
                    candidate = datetime(
                        day.year, day.month, day.day, hour, minute
                    )
                    if candidate >= start:
                        return candidate
        day += timedelta(days=1)

    raise ValueError(f"cron expression never fires: {expression!r}")

from __future__ import annotations

import re


_ALIGNMENTS = (None, "left", "right", "center")
_DELIMITER_RE = re.compile(r"^:?-+:?$")


def _cell_text(value) -> str:
    text = "" if value is None else str(value)
    return text.replace("|", "\\|")


def _pad(text: str, width: int, alignment: str | None) -> str:
    padding = width - len(text)
    if alignment == "right":
        return " " * padding + text
    if alignment == "center":
        left = padding // 2
        return " " * left + text + " " * (padding - left)
    return text + " " * padding


def _delimiter_cell(width: int, alignment: str | None) -> str:
    if alignment == "left":
        return ":" + "-" * (width - 1)
    if alignment == "right":
        return "-" * (width - 1) + ":"
    if alignment == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


def _render_row(cells: list[str]) -> str:
    return "| " + " | ".join(cells) + " |"


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    column_count = len(header)
    if align is None:
        alignments: list[str | None] = [None] * column_count
    else:
        if len(align) != column_count:
            raise ValueError("align must have one entry per column")
        alignments = list(align)
        for alignment in alignments:
            if alignment not in _ALIGNMENTS:
                raise ValueError(f"invalid alignment: {alignment!r}")

    header_cells = [_cell_text(value) for value in header]
    row_cells: list[list[str]] = []
    for row in rows:
        if len(row) > column_count:
            raise ValueError("row has more cells than the header")
        cells = [_cell_text(value) for value in row]
        cells.extend([""] * (column_count - len(cells)))
        row_cells.append(cells)

    widths = []
    for index in range(column_count):
        width = max(
            [3, len(header_cells[index])]
            + [len(row[index]) for row in row_cells]
        )
        widths.append(width)

    lines = [
        _render_row(
            [
                _pad(header_cells[index], widths[index], alignments[index])
                for index in range(column_count)
            ]
        ),
        _render_row(
            [
                _delimiter_cell(widths[index], alignments[index])
                for index in range(column_count)
            ]
        ),
    ]
    for row in row_cells:
        lines.append(
            _render_row(
                [
                    _pad(row[index], widths[index], alignments[index])
                    for index in range(column_count)
                ]
            )
        )

    return "\n".join(lines)


def _split_row(line: str) -> list[str]:
    text = line.strip()
    if text.startswith("|"):
        text = text[1:]
    if text.endswith("|") and not text.endswith("\\|"):
        text = text[:-1]

    cells = re.split(r"(?<!\\)\|", text)
    return [cell.strip().replace("\\|", "|") for cell in cells]


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.splitlines()
    if len(lines) < 2:
        raise ValueError("not a Markdown table")

    header = _split_row(lines[0])
    delimiter_cells = _split_row(lines[1])

    if len(delimiter_cells) != len(header):
        raise ValueError("delimiter row has the wrong number of cells")

    alignments: list[str | None] = []
    for cell in delimiter_cells:
        if _DELIMITER_RE.fullmatch(cell) is None:
            raise ValueError(f"invalid delimiter cell: {cell!r}")
        left = cell.startswith(":")
        right = cell.endswith(":")
        if left and right:
            alignments.append("center")
        elif left:
            alignments.append("left")
        elif right:
            alignments.append("right")
        else:
            alignments.append(None)

    rows: list[list[str]] = []
    for line in lines[2:]:
        row = _split_row(line)
        if len(row) != len(header):
            raise ValueError("row has the wrong number of cells")
        rows.append(row)

    return header, rows, alignments

