from __future__ import annotations


class ParseError(ValueError):
    def __init__(self, lineno: int, message: str):
        super().__init__(f"line {lineno}: {message}")
        self.lineno = lineno


class InterpolationError(ValueError):
    pass


def parse(text: str) -> dict[str, dict[str, str]]:
    """Parse INI text."""
    sections: dict[str, dict[str, str]] = {}
    current_section: str | None = None
    current_key: str | None = None

    for lineno, raw_line in enumerate(text.splitlines(), 1):
        if not raw_line.strip():
            current_key = None
            continue

        stripped = raw_line.strip()
        if stripped.startswith("#") or stripped.startswith(";"):
            current_key = None
            continue

        if (
            raw_line[:1].isspace()
            and current_key is not None
            and current_section is not None
        ):
            sections[current_section][current_key] += "\n" + stripped
            continue

        current_key = None

        if stripped.startswith("[") and stripped.endswith("]"):
            name = stripped[1:-1].strip()
            if name not in sections:
                sections[name] = {}
            current_section = name
            continue

        equals = stripped.find("=")
        colon = stripped.find(":")
        positions = [position for position in (equals, colon) if position != -1]
        if not positions:
            raise ParseError(lineno, "expected a section header or key/value pair")

        split_at = min(positions)
        key = stripped[:split_at].strip().lower()
        value = stripped[split_at + 1 :].strip()

        if current_section is None:
            raise ParseError(lineno, "key before any section")
        if not key:
            raise ParseError(lineno, "empty key")

        sections[current_section][key] = value
        current_key = key

    cache: dict[tuple[str, str], str] = {}
    stack: list[tuple[str, str]] = []

    def resolve(section: str, key: str) -> str:
        identity = (section, key)
        if identity in cache:
            return cache[identity]
        if identity in stack:
            cycle = " -> ".join(
                f"{sec}:{name}" for sec, name in stack + [identity]
            )
            raise InterpolationError(f"interpolation cycle: {cycle}")

        stack.append(identity)
        try:
            result = interpolate(sections[section][key], section)
        finally:
            stack.pop()

        cache[identity] = result
        return result

    def interpolate(value: str, section: str) -> str:
        pieces: list[str] = []
        index = 0
        length = len(value)

        while index < length:
            char = value[index]
            if char != "$":
                pieces.append(char)
                index += 1
                continue

            if index + 1 < length and value[index + 1] == "$":
                pieces.append("$")
                index += 2
                continue

            if index + 1 < length and value[index + 1] == "{":
                end = value.find("}", index + 2)
                if end == -1:
                    pieces.append("$")
                    index += 1
                    continue

                reference = value[index + 2 : end]
                if ":" in reference:
                    ref_section, ref_key = reference.split(":", 1)
                    ref_section = ref_section.strip()
                else:
                    ref_section = section
                    ref_key = reference

                ref_key = ref_key.strip().lower()
                if (
                    ref_section not in sections
                    or ref_key not in sections[ref_section]
                ):
                    raise InterpolationError(
                        f"missing interpolation reference: {reference!r}"
                    )

                pieces.append(resolve(ref_section, ref_key))
                index = end + 1
                continue

            pieces.append("$")
            index += 1

        return "".join(pieces)

    return {
        section: {key: resolve(section, key) for key in values}
        for section, values in sections.items()
    }

